INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u6-C12','kor',5,2,'u6',2,'구성 요소를 생각하며 읽기 — 인물, 사건, 배경을 생각하며 읽으면 이야기의 전체 흐름과 의미를 잘 파악할 수 있다',ARRAY['6국05-03 문학']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u6-C13','kor',5,2,'u6',4,'사건에 따라 바뀌는 마음 — 사건이 바뀔 때마다 인물의 마음이 어떻게 달라지는지 차례대로 따라가며 읽는다',ARRAY['6국05-03 문학']::text[],13) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
