INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u6-C18','kor',5,2,'u6',4,'인상 깊은 장면 — 인상 깊은 장면은 사람마다 다를 수 있고, 고른 까닭을 이야기 속 근거와 함께 말한다',ARRAY['6국05-04 문학']::text[],18) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
