INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u6-C20','kor',5,2,'u6',7,'극본 — 연극을 하려고 쓴 글',ARRAY['6국05-03 문학']::text[],20) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u6-C21','kor',5,2,'u6',7,'해설 — 대체로 극본의 첫 부분에서 때, 곳, 등장인물, 무대 배경 같은 것을 설명하는 부분으로, 인물의 감정을 알려 주지는 않는다',ARRAY['6국05-03 문학']::text[],21) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u6-C22','kor',5,2,'u6',7,'대사 — 극본에서 인물이 직접 하는 말',ARRAY['6국05-03 문학']::text[],22) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u6-C23','kor',5,2,'u6',7,'지문 — 인물의 표정, 행동, 말투 같은 것을 설명하려고 괄호로 나타낸 부분으로, 소리 내어 말하지 않고 몸과 목소리로 표현한다',ARRAY['6국05-03 문학']::text[],23) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u6-C24','kor',5,2,'u6',7,'이야기 글과 극본 — 이야기 글은 줄글로 읽는 사람에게 들려주고, 극본은 공연하려고 대사와 지문으로 나누어 쓴다',ARRAY['6국05-03 문학']::text[],24) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u6-C25','kor',5,2,'u6',7,'극본 낭독하기 — 역할을 나누어 해설부터 차례대로 읽고, 지문을 보고 알맞은 목소리와 표정으로 대사를 한다',ARRAY['6국05-03 문학']::text[],25) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u6-C26','kor',5,2,'u6',7,'장면을 상상하며 읽기 — 해설과 지문을 보고 무대 위 장면과 인물의 움직임을 떠올리며 극본을 읽는다',ARRAY['6국05-03 문학']::text[],26) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u6-C27','kor',5,2,'u6',9,'해설·대사·지문 이어 읽기 — 대사만이 아니라 해설·대사·지문을 이어 읽어야 사건의 흐름과 인물의 마음을 제대로 감상할 수 있다',ARRAY['6국05-03 문학']::text[],27) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
