INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u6-C30','kor',5,2,'u6',9,'역할 수행 학습의 차례 — 상황 설정하기 → 준비 및 연습하기 → 실연하기 → 평가하기',ARRAY['6국05-03 문학']::text[],30) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u6-C31','kor',5,2,'u6',9,'맡은 인물에게 묻기 — 「이 인물은 왜 이렇게 말했을까?」를 물으면 그 순간 인물의 마음을 깊이 이해할 수 있다',ARRAY['6국05-04 문학']::text[],31) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
