INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u3_L05_basic#5','math',5,2,'u3','L05','g5_2_math_u3_L05_basic','lesson_basic','M5-2-u3-C5',2,'mc','auto','오각형 ㄱㄴㄷㄹㅁ은 그림의 대칭축을 따라 접으면 완전히 겹치는 선대칭도형이에요. 점 ㄱ의 대응점은 어느 것인가요?',ARRAY['M5-2-u3-X06','M5-2-u3-X15']::text[],true,'{"seq":5,"concept":"M5-2-u3-C5","difficulty":2,"kind":"mc","stem":"오각형 ㄱㄴㄷㄹㅁ은 그림의 대칭축을 따라 접으면 완전히 겹치는 선대칭도형이에요. 점 ㄱ의 대응점은 어느 것인가요?","options":[{"t":"점 ㄷ","correct":true},{"t":"점 ㄴ","mis":"M5-2-u3-X06"},{"t":"점 ㄹ","mis":"M5-2-u3-X06"},{"t":"점 ㄱ","mis":"M5-2-u3-X15"}],"explanation":["대응점은 대칭축을 따라 접었을 때 겹치는 점이에요.","점 ㄱ을 대칭축 건너편으로 같은 거리만큼 옮기면 점 ㄷ이에요.","그래서 점 ㄱ의 대응점은 점 ㄷ이에요."],"asset":{"type":"geo","items":[{"w":120,"h":148.0,"pts":{"ㄱ":[0,64.0,"w"],"ㄴ":[60,24.0,"n"],"ㄷ":[120,64.0,"e"],"ㄹ":[100,124.0,"se"],"ㅁ":[20,124.0,"sw"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ"]],"seg":[[[60,0.0],[60,148.0]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"육각형 ㄱㄴㄷㄹㅁㅂ은 그림의 대칭축을 따라 접으면 완전히 겹치는 선대칭도형이에요. 점 ㄷ의 대응점은 어느 것인가요?","options":[{"t":"점 ㅂ","correct":true},{"t":"점 ㄹ","mis":"M5-2-u3-X06"},{"t":"점 ㄱ","mis":"M5-2-u3-X06"},{"t":"점 ㄷ","mis":"M5-2-u3-X15"}],"explanation":["대응점은 대칭축을 따라 접었을 때 겹치는 점이에요.","점 ㄷ을 대칭축 건너편으로 같은 거리만큼 옮기면 점 ㅂ이에요.","그래서 점 ㄷ의 대응점은 점 ㅂ이에요."],"asset":{"type":"geo","items":[{"w":120,"h":148.0,"pts":{"ㄱ":[20,24.0,"nw"],"ㄴ":[100,24.0,"ne"],"ㄷ":[120,64.0,"e"],"ㄹ":[80,124.0,"s"],"ㅁ":[40,124.0,"s"],"ㅂ":[0,64.0,"w"]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ"]],"seg":[[[60,0.0],[60,148.0]]]}],"tag":false}},{"stem":"칠각형 ㄱㄴㄷㄹㅁㅂㅅ은 그림의 대칭축을 따라 접으면 완전히 겹치는 선대칭도형이에요. 점 ㄴ의 대응점은 어느 것인가요?","options":[{"t":"점 ㅂ","correct":true},{"t":"점 ㄷ","mis":"M5-2-u3-X06"},{"t":"점 ㄹ","mis":"M5-2-u3-X06"},{"t":"점 ㄴ","mis":"M5-2-u3-X15"}],"explanation":["대응점은 대칭축을 따라 접었을 때 겹치는 점이에요.","점 ㄴ을 대칭축 건너편으로 같은 거리만큼 옮기면 점 ㅂ이에요.","그래서 점 ㄴ의 대응점은 점 ㅂ이에요."],"asset":{"type":"geo","items":[{"w":168.0,"h":120,"pts":{"ㄱ"